const {app,BrowserWindow,session,ipcMain}=require('electron');
const fs=require('node:fs'),path=require('node:path'),os=require('node:os');
const {build}=require('esbuild');
const root=path.resolve(__dirname,'../..'),temporary=fs.mkdtempSync(path.join(os.tmpdir(),'stable-template-ui-'));
app.setPath('userData',temporary);app.disableHardwareAcceleration();
let win;
(async()=>{
 await app.whenReady();session.defaultSession.webRequest.onBeforeRequest((d,cb)=>cb({cancel:/^https?:/.test(d.url)}));
 const {TemplateLibrary}=require('../../desktop/services/template-library.cjs'),settings={};
 const lib=new TemplateLibrary({getSetting:k=>settings[k],setSetting:(k,v)=>settings[k]=v},temporary),items=lib.list();
 ipcMain.handle('template-test:detail',(_e,id,options)=>lib.detail(id,options));
 const preload=path.join(temporary,'preload.cjs');
 fs.writeFileSync(preload,"const {contextBridge,ipcRenderer}=require('electron');contextBridge.exposeInMainWorld('templateTest',{detail:(id,options)=>ipcRenderer.invoke('template-test:detail',id,options)});");
 const bundle=(await build({stdin:{contents:`import React from 'react';import {createRoot} from 'react-dom/client';import {TemplateLibrary} from './src/TemplateLibrary';
 const items=${JSON.stringify(items)};window.used=[];window.stable={templates:{list:async()=>items,detail:(id,options)=>window.templateTest.detail(id,options),save:async(id,value)=>{Object.assign(items.find(x=>x.id===id),value);return [...items]},import:async()=>items,use:async id=>{window.used.push(id);return {draftPrompt:'test'}}}};
 createRoot(document.getElementById('root')).render(<TemplateLibrary skills={[{id:'frontend-slides',name:'Frontend Slides 演示文稿',enabled:true}]} onUse={()=>{window.draftOpened=true}}/>);`,loader:'tsx',resolveDir:root},bundle:true,write:false,jsx:'automatic',format:'iife',plugins:[{name:'css',setup(b){b.onLoad({filter:/\.css$/},()=>({contents:'',loader:'js'}))}}],define:{'process.env.NODE_ENV':'"production"'}})).outputFiles[0].text;
 const css=fs.readFileSync(path.join(root,'src/styles/template-library.css'),'utf8');
 win=new BrowserWindow({width:1440,height:1000,show:false,webPreferences:{preload,offscreen:true,backgroundThrottling:false,sandbox:true,contextIsolation:true,nodeIntegration:false}});
 await win.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(`<html><style>*{box-sizing:border-box}body{margin:0;font:15px 'Segoe UI',sans-serif;--color-paper:#fff;--color-ink:#252525;--color-muted:#777}#root{height:100vh}${css}</style><div id="root"></div></html>`));await win.webContents.executeJavaScript(bundle);
 const run=code=>win.webContents.executeJavaScript(`(async()=>{${code}})()`);
 win.webContents.enableDeviceEmulation({screenPosition:'desktop',viewSize:{width:1440,height:1000},deviceScaleFactor:1,scale:1});
 await run(`window.wait=async f=>{for(let i=0;i<300;i++){if(f())return;await new Promise(r=>setTimeout(r,20))}throw Error('UI timeout')};window.expect=(v,m)=>{if(!v)throw Error(m)};await wait(()=>document.querySelectorAll('.template-card').length===47);await wait(()=>document.querySelectorAll('.template-thumbnail [data-loaded=true]').length>=3);
 const cards=[...document.querySelectorAll('.template-card')],names=cards.map(c=>c.querySelector('.template-card-info>button').textContent);
 expect(names.every(n=>/[\u4e00-\u9fff]/.test(n)),'Template names are not Chinese');expect(!names.includes('项目启动方案')&&!names.includes('品牌故事长页'),'Retired templates remain');
 expect(cards.slice(1,35).every(c=>c.querySelector('[data-original=true]')),'Original samples are not ahead');expect(cards.slice(-12).every(c=>!c.querySelector('[data-original=true]')),'Classic presets are not last');`);
 const out=path.resolve(root,'qa-artifacts/frontend-slides-20261104');fs.mkdirSync(out,{recursive:true});
 const capture=async name=>{await new Promise(r=>setTimeout(r,700));fs.writeFileSync(path.join(out,name),(await win.webContents.capturePage()).toPNG())};
 await capture('gallery.png');
 await run(`document.querySelector('[aria-label="收藏 像素轨道"]').click();await wait(()=>document.querySelector('[aria-label="取消收藏 像素轨道"]'));document.querySelectorAll('[role=tab]')[1].click();await wait(()=>document.querySelectorAll('.template-card').length===1);document.querySelector('.template-cover').click();await wait(()=>document.querySelector('dialog').open);await wait(()=>document.querySelectorAll('.template-preview img[data-loaded=true]').length===3);
 expect([...document.querySelectorAll('.template-preview img')].every(i=>i.naturalWidth>=1280&&i.naturalHeight>=720),'Original images did not decode');expect(!document.querySelector('.template-preview iframe'),'Original preview uses adapted iframe');expect(document.querySelector('.template-detail h2').textContent==='像素轨道','Detail name is not Chinese');`);
 await capture('original-preview.png');
 await run(`document.querySelector('.template-settings').click();await wait(()=>document.querySelector('form'));document.querySelector('form').requestSubmit();await wait(()=>!document.querySelector('form'));document.querySelector('footer .template-primary').click();await wait(()=>window.used.length===1&&window.draftOpened);expect(window.used[0]==='frontend-slides-8-bit-orbit','Wrong template selected');expect(!document.querySelector('dialog').open,'Dialog not closed');
 document.querySelectorAll('[role=tab]')[0].click();const input=document.querySelector('[aria-label="搜索模板"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'醒目信号');input.dispatchEvent(new Event('input',{bubbles:true}));await wait(()=>document.querySelectorAll('.template-card').length===1);document.querySelector('.template-cover').click();await wait(()=>document.querySelector('dialog').open);await wait(()=>document.querySelector('.template-preview iframe[data-loaded=true]'));
 expect(document.querySelector('.template-preview iframe').contentDocument.body.innerText.includes('把想法'),'Classic preview missing');expect(document.querySelector('.template-detail h2').textContent==='醒目信号','Classic name is not Chinese');`);
 await capture('classic-preview.png');
 console.log('TEMPLATE_UI_PASS '+out);win.destroy();app.exit(0);
})().catch(e=>{console.error(e.stack);win?.destroy();app.exit(1)});
